-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('5a94eeb9-64b0-50ce-a51f-4d8aef658f1e'::uuid, '57f93e94-e689-519a-983c-74616a2b3ea8'::uuid, 'Quelles sont les trois couleurs primaires en peinture ?', 'mcq', '["Magenta, cyan, jaune","Rouge, vert, bleu","Noir, blanc, gris","Orange, violet, vert"]'::jsonb, 0, 'On ne peut pas les obtenir en mélangeant d’autres couleurs.', 1),
    ('afe0e2af-df04-5890-9c03-4314e8e57785'::uuid, '57f93e94-e689-519a-983c-74616a2b3ea8'::uuid, 'Quelle est la complémentaire du bleu ?', 'mcq', '["L’orange","Le vert","Le violet","Le rouge"]'::jsonb, 0, 'Elles se font face sur le cercle chromatique.', 2),
    ('9aef7d17-6054-54c6-a78d-ecb28b266b12'::uuid, '57f93e94-e689-519a-983c-74616a2b3ea8'::uuid, 'Deux couleurs complémentaires mélangées donnent un gris.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles s’éteignent mutuellement ; côte à côte, au contraire, elles se renforcent.', 3),
    ('f34756ff-8c86-551b-868a-3a3ee673db29'::uuid, '57f93e94-e689-519a-983c-74616a2b3ea8'::uuid, 'Les couleurs froides semblent…', 'mcq', '["Reculer dans l’image","Avancer vers le spectateur","Disparaître","Vibrer"]'::jsonb, 0, 'C’est un moyen simple de suggérer la profondeur.', 4),
    ('561466f8-a279-57ec-9180-aeec05f57d8b'::uuid, '57f93e94-e689-519a-983c-74616a2b3ea8'::uuid, 'Le vert est une couleur secondaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il naît du mélange du jaune et du cyan.', 5),
    ('c409503a-49f8-50f3-a979-71bda2042871'::uuid, '57f93e94-e689-519a-983c-74616a2b3ea8'::uuid, 'Que désigne la valeur d’une couleur ?', 'mcq', '["Son degré de clair ou de sombre","Son prix","Son intensité","Sa température"]'::jsonb, 0, 'À ne pas confondre avec la saturation.', 6),
    ('ed28d12e-e515-519e-8ba6-2e2e6a959a8c'::uuid, '57f93e94-e689-519a-983c-74616a2b3ea8'::uuid, 'La saturation désigne l’intensité d’une couleur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une couleur peu saturée tire vers le gris.', 7),
    ('00e45f39-45d4-5d6d-ba08-46ef0c79c1b2'::uuid, '57f93e94-e689-519a-983c-74616a2b3ea8'::uuid, 'Comment obtient-on du violet ?', 'mcq', '["En mélangeant du magenta et du cyan","En mélangeant du jaune et du rouge","En mélangeant du vert et du bleu","En ajoutant du blanc au rouge"]'::jsonb, 0, 'Deux primaires donnent une secondaire.', 8),
    ('8a47d18a-2119-501d-9c6c-955cc46096f5'::uuid, '3bc3083b-b921-53c4-88ef-314bdabf5e0c'::uuid, 'Vers quoi convergent les lignes en perspective linéaire ?', 'mcq', '["Le point de fuite","Le centre du tableau","Le cadre","Le premier plan"]'::jsonb, 0, 'Il se situe sur la ligne d’horizon, à hauteur d’œil.', 1),
    ('db3f28a3-6f7c-558e-9e15-7a7d239d9752'::uuid, '3bc3083b-b921-53c4-88ef-314bdabf5e0c'::uuid, 'La perspective linéaire a été formalisée à la Renaissance.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Brunelleschi et Alberti en posent les règles au XVe siècle.', 2),
    ('7ce7517e-9fbe-57e2-a95a-4f832a1e0378'::uuid, '3bc3083b-b921-53c4-88ef-314bdabf5e0c'::uuid, 'En perspective atmosphérique, les objets lointains sont…', 'mcq', '["Plus pâles et moins contrastés","Plus vifs","Plus nets","Plus sombres"]'::jsonb, 0, 'L’air épaissit et bleuit la vision au loin.', 3),
    ('66f2562e-758b-59e6-9e0a-437c5c42b21f'::uuid, '3bc3083b-b921-53c4-88ef-314bdabf5e0c'::uuid, 'La superposition indique que…', 'mcq', '["Ce qui cache est devant","Ce qui cache est derrière","Les objets sont de même taille","L’image est plate"]'::jsonb, 0, 'C’est le procédé le plus élémentaire de profondeur.', 4),
    ('60507909-f8b0-5e3c-88e4-26776a8bbb2e'::uuid, '3bc3083b-b921-53c4-88ef-314bdabf5e0c'::uuid, 'Une vue d’angle nécessite deux points de fuite.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La vue frontale n’en demande qu’un.', 5),
    ('d1ad5237-f88a-5cd4-be74-68b0074e7ef5'::uuid, '3bc3083b-b921-53c4-88ef-314bdabf5e0c'::uuid, 'Le cubisme…', 'mcq', '["Montre plusieurs points de vue à la fois","Perfectionne la perspective","Copie la photographie","Supprime la couleur"]'::jsonb, 0, 'Braque et Picasso brisent le point de vue unique.', 6),
    ('03ad2fdf-df63-5ba5-8270-afa96095e878'::uuid, '3bc3083b-b921-53c4-88ef-314bdabf5e0c'::uuid, 'L’étagement place les éléments lointains plus haut sur la feuille.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un procédé ancien, très présent avant la Renaissance.', 7),
    ('b43e7a22-c0e5-5c1e-b16d-2c220f0c2557'::uuid, '3bc3083b-b921-53c4-88ef-314bdabf5e0c'::uuid, 'La ligne d’horizon correspond…', 'mcq', '["À la hauteur d’œil du spectateur","Au bord haut du tableau","Au sol","Au centre exact de l’image"]'::jsonb, 0, 'Elle détermine si l’on regarde de haut ou de bas.', 8),
    ('a193bcda-16c2-521e-a161-03956ad18b01'::uuid, 'c8ee7335-7b09-575f-945a-cb4ac89db906'::uuid, 'Le collage introduit…', 'mcq', '["Des éléments du réel dans l’œuvre","De la perspective","Des couleurs primaires","De la symétrie"]'::jsonb, 0, 'Il apparaît au début du XXe siècle avec le cubisme.', 1),
    ('81457cb1-b2a2-57bd-a54e-c59a26511b83'::uuid, 'c8ee7335-7b09-575f-945a-cb4ac89db906'::uuid, 'Le support d’une œuvre est un choix neutre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Format, texture, matière du support changent le sens de l’image.', 2),
    ('2ba2bb9c-13c8-5800-a2c9-9a7c84654f59'::uuid, 'c8ee7335-7b09-575f-945a-cb4ac89db906'::uuid, 'Quelle technique consiste à laisser couler la peinture ?', 'mcq', '["Le dripping","Le frottage","Le pochoir","Le glacis"]'::jsonb, 0, 'Jackson Pollock en a fait sa signature.', 3),
    ('0ec1862f-6a3f-5f2a-8d0c-a77f84fcc8cf'::uuid, 'c8ee7335-7b09-575f-945a-cb4ac89db906'::uuid, 'Le frottage a été développé par…', 'mcq', '["Max Ernst","Claude Monet","Auguste Rodin","Andy Warhol"]'::jsonb, 0, 'Il révèle par frottement le relief d’une surface.', 4),
    ('cdc4d430-e9f8-5778-ab55-bddaebe2e5a9'::uuid, 'c8ee7335-7b09-575f-945a-cb4ac89db906'::uuid, 'Une même couleur produit le même effet quel que soit l’outil.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Pinceau, rouleau, éponge : la trace change tout.', 5),
    ('b39a60b1-d37e-5647-9ead-ff526cc2898a'::uuid, 'c8ee7335-7b09-575f-945a-cb4ac89db906'::uuid, 'Qu’est-ce que le fusain ?', 'mcq', '["Un bâtonnet de charbon de bois pour dessiner","Une peinture à l’huile","Un papier épais","Un vernis"]'::jsonb, 0, 'Il permet des noirs profonds et s’estompe facilement.', 6),
    ('82c799f6-7add-5afc-a40c-c525a0c4457f'::uuid, 'c8ee7335-7b09-575f-945a-cb4ac89db906'::uuid, 'Agrandir un dessin au format monumental change sa perception.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le corps du spectateur entre alors en rapport avec l’œuvre.', 7),
    ('c88cdce0-6458-5727-9663-6a118e6cb04a'::uuid, 'c8ee7335-7b09-575f-945a-cb4ac89db906'::uuid, 'Provoquer un accident et le conserver est…', 'mcq', '["Un savoir-faire artistique","Une erreur","Interdit","Un manque de technique"]'::jsonb, 0, 'Le hasard maîtrisé est une démarche assumée.', 8),
    ('d7979dff-556c-5ecd-b3e1-6c00887ec6a0'::uuid, '9f5063b7-f0b9-542e-82aa-95d7b781f46c'::uuid, 'Que désigne le hors-champ ?', 'mcq', '["Ce qui est hors du cadre mais reste présent","Le fond de l’image","Le cadre en bois","Le premier plan"]'::jsonb, 0, 'Il travaille l’imagination du spectateur.', 1),
    ('04cedb35-b052-543d-b521-6f628e6185e9'::uuid, '9f5063b7-f0b9-542e-82aa-95d7b781f46c'::uuid, 'Une œuvre in situ est conçue pour un lieu précis.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La déplacer la dénature.', 2),
    ('4d316d9f-ccc0-5477-9fea-b058ac57fd0c'::uuid, '9f5063b7-f0b9-542e-82aa-95d7b781f46c'::uuid, 'Le titre d’une œuvre…', 'mcq', '["Fait partie de l’œuvre et oriente sa lecture","Est une simple étiquette","Est toujours descriptif","Est choisi par le musée"]'::jsonb, 0, '*Sans titre* est lui-même un choix.', 3),
    ('66e2cade-9339-5be6-8cb5-0ecb83bfe3fe'::uuid, '9f5063b7-f0b9-542e-82aa-95d7b781f46c'::uuid, 'L’art cinétique joue avec…', 'mcq', '["Le mouvement","Le silence","La photographie","L’écriture"]'::jsonb, 0, 'Mouvement réel de l’œuvre ou déplacement du spectateur.', 4),
    ('4a8059a2-6b71-5589-92bb-c31558947768'::uuid, '9f5063b7-f0b9-542e-82aa-95d7b781f46c'::uuid, 'Cadrer, c’est aussi décider ce qu’on cache.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le choix du cadre est un acte de sens.', 5),
    ('fc468b88-7c3e-570b-928a-e6bc65c4ebd2'::uuid, '9f5063b7-f0b9-542e-82aa-95d7b781f46c'::uuid, 'Une installation se caractérise par le fait que…', 'mcq', '["Le spectateur y entre ou la parcourt","Elle est toujours peinte","Elle tient dans une main","Elle est numérique"]'::jsonb, 0, 'Elle occupe et transforme un espace.', 6),
    ('52a922ef-b933-5d60-9868-b272419fe3eb'::uuid, '9f5063b7-f0b9-542e-82aa-95d7b781f46c'::uuid, 'Changer une œuvre de lieu ne change jamais son sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Vitrine, musée, rue : le contexte fait partie de la réception.', 7),
    ('34b0e51a-e0da-5a10-ad53-9af5ca872f89'::uuid, '9f5063b7-f0b9-542e-82aa-95d7b781f46c'::uuid, 'Une œuvre participative suppose…', 'mcq', '["Une action du spectateur","Un guide","Un grand format","Un cadre doré"]'::jsonb, 0, 'Sans son intervention, l’œuvre reste incomplète.', 8),
    ('f24c232e-ccc9-5af6-a8f9-4f0597d1a1df'::uuid, 'bc6e3477-69a1-52b6-ab6e-e51dd49c6fdf'::uuid, 'Que désigne la connotation d’une image ?', 'mcq', '["Ce qu’elle suggère au-delà de ce qu’elle montre","Ce qu’elle montre littéralement","Son format","Son auteur"]'::jsonb, 0, 'Valeurs, émotions, associations d’idées.', 1),
    ('a87fef59-11ac-50b3-97ca-1b001fff40db'::uuid, 'bc6e3477-69a1-52b6-ab6e-e51dd49c6fdf'::uuid, 'L’accroche d’une publicité sert à ancrer le sens de l’image.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sans texte, l’image reste souvent ambiguë.', 2),
    ('38d1c01d-4868-5e30-b69e-57547ffd8bfa'::uuid, 'bc6e3477-69a1-52b6-ab6e-e51dd49c6fdf'::uuid, 'Le détournement consiste à…', 'mcq', '["Réutiliser des codes existants pour les retourner","Copier une œuvre","Restaurer un tableau","Photographier une publicité"]'::jsonb, 0, 'La pratique vient notamment des situationnistes.', 3),
    ('50b00a2b-1dac-5ccb-9e5a-9ad77ec456b8'::uuid, 'bc6e3477-69a1-52b6-ab6e-e51dd49c6fdf'::uuid, 'La dénotation, c’est…', 'mcq', '["Ce que l’image montre littéralement","Ce qu’elle évoque","Sa valeur marchande","Son cadre"]'::jsonb, 0, 'Le niveau descriptif, avant interprétation.', 4),
    ('ecda17c6-5577-5be2-98f6-781095012a67'::uuid, 'bc6e3477-69a1-52b6-ab6e-e51dd49c6fdf'::uuid, 'Une image publicitaire est une image neutre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Chaque choix (cadrage, lumière, retouche) sert une intention commerciale.', 5),
    ('473717f9-b223-59b3-b7b4-b461a1adf1c3'::uuid, 'bc6e3477-69a1-52b6-ab6e-e51dd49c6fdf'::uuid, 'Quelle question est la plus utile pour lire une image ?', 'mcq', '["Qui parle, à qui, pour quoi ?","Combien coûte-t-elle ?","Quelle est sa taille ?","Qui l’a imprimée ?"]'::jsonb, 0, 'Elle fait apparaître l’intention derrière l’image.', 6),
    ('666b0da6-f457-54a2-a834-d1e2ec64dde8'::uuid, 'bc6e3477-69a1-52b6-ab6e-e51dd49c6fdf'::uuid, 'La retouche numérique fait partie des procédés publicitaires courants.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle façonne des corps et des objets idéalisés.', 7),
