    ('113afa36-77d0-5b3d-a819-40a0eba589a8'::uuid, '9010e898-5545-54fc-945c-7940155a1eba'::uuid, 'Quelle technique consiste à retirer de la matière ?', 'mcq', '["La taille","Le modelage","L’assemblage","Le moulage"]'::jsonb, 0, 'On taille la pierre ou le bois ; on modèle l’argile.', 1),
